//! Parity and regression tests for the melotts family.
//!
//! Pinned fixtures reside in `testdata/tts_melotts/`, generated by
//! `tools/gen_melotts_fixtures.py` against mlx-audio 0.5.7 commit
//! `e1b19b9054bf163f5d812221a54fcc346f1890e9` (mlx 0.32.3). The generator
//! runs the true reference modules (text.py, the post-G2P mapping, the
//! tiny BERT on pinned ids, and the instrumented `Model.infer`) against a
//! tiny seeded model. The G2P and the wordpiece tokenizer are pinned
//! stand-ins: g2p_en/cmudict are not installed in the fixture venv and
//! the bert-base vocab is not cached (see the family README).

use std::path::{Path, PathBuf};

use serde_json::Value;

use super::text::{
    add_blank_interleave, cleaned_text_to_sequence, default_symbols, post_replace_ph, refine_ph,
    text_normalize,
};
use super::Model;

fn testdata(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("testdata/tts_melotts")
        .join(name)
}

fn read_json(path: &Path) -> Value {
    let text = std::fs::read_to_string(path).expect("fixture json");
    serde_json::from_str(&text).expect("fixture json")
}

fn f32_vec(value: &Value) -> Vec<f32> {
    value
        .as_array()
        .expect("values")
        .iter()
        .map(|v| v.as_f64().expect("value") as f32)
        .collect()
}

fn i32_vec(value: &Value) -> Vec<i32> {
    value
        .as_array()
        .expect("ids")
        .iter()
        .map(|v| v.as_i64().expect("id") as i32)
        .collect()
}

fn max_abs_diff(a: &[f32], b: &[f32]) -> f32 {
    assert_eq!(
        a.len(),
        b.len(),
        "length mismatch: {} vs {}",
        a.len(),
        b.len()
    );
    // `f32::max` silently drops NaN, so a NaN output would read as a zero
    // diff. Propagate NaN explicitly so the `<= tolerance` check fails.
    a.iter()
        .zip(b)
        .map(|(x, y)| (x - y).abs())
        .fold(0.0f32, |m, d| {
            if m.is_nan() || d.is_nan() {
                f32::NAN
            } else {
                m.max(d)
            }
        })
}

fn assert_close(got: &[f32], want: &[f32], tolerance: f32, stage: &str) {
    let diff = max_abs_diff(got, want);
    assert!(
        diff <= tolerance,
        "{stage}: diff {diff} exceeds {tolerance} (got {} values)",
        got.len()
    );
}

/// Measured maximum differences against the fixture traces when the
/// gates were frozen; assertions use these values, not re-measured ones.
/// String stages and ids are exact; the whole model path is f32 conv and
/// matmul reordering.
const FEATURE_TOLERANCE: f32 = 2e-4;
const AUDIO_TOLERANCE: f32 = 5e-4;

#[test]
fn text_normalize_matches_the_reference_cases() {
    let traces = read_json(&testdata("frontend/traces.json"));
    for case in traces["normalize_cases"].as_array().expect("cases") {
        let got = text_normalize(case["input"].as_str().expect("input"));
        assert_eq!(
            got,
            case["output"].as_str().expect("output"),
            "case {}",
            case["name"]
        );
    }
}

#[test]
fn post_g2p_mapping_matches_the_reference() {
    let traces = read_json(&testdata("frontend/traces.json"));
    let symbols = traces["symbols"]
        .as_array()
        .expect("symbols")
        .iter()
        .map(|v| v.as_str().expect("symbol").to_string())
        .collect::<Vec<_>>();
    assert_eq!(symbols, default_symbols(), "fixture symbol table");
    for case in traces["g2p_cases"].as_array().expect("cases") {
        let mut phones = Vec::new();
        let mut tones = Vec::new();
        for word in case["word_phones"].as_array().expect("words") {
            for ph in word.as_array().expect("phones") {
                let (p, t) = refine_ph(ph.as_str().expect("phone"));
                phones.push(post_replace_ph(&p, &symbols, &super::text::PU_SYMBOLS));
                tones.push(t);
            }
        }
        // The reference g2p wraps the phones with pads.
        phones.insert(0, "_".to_string());
        phones.push("_".to_string());
        tones.insert(0, 0);
        tones.push(0);
        assert_eq!(
            phones,
            {
                case["phones"]
                    .as_array()
                    .expect("phones")
                    .iter()
                    .map(|v| v.as_str().expect("phone").to_string())
                    .collect::<Vec<_>>()
            },
            "case {} phones",
            case["name"]
        );
        assert_eq!(
            tones,
            i32_vec(&case["tones"]),
            "case {} tones",
            case["name"]
        );
        let (phone_ids, tone_ids, lang_ids) =
            cleaned_text_to_sequence(&phones, &tones, "EN", &symbols);
        assert_eq!(
            phone_ids,
            i32_vec(&case["phone_ids"]),
            "case {} ids",
            case["name"]
        );
        assert_eq!(
            tone_ids,
            i32_vec(&case["tone_ids"]),
            "case {} tones",
            case["name"]
        );
        assert_eq!(
            lang_ids,
            i32_vec(&case["lang_ids"]),
            "case {} langs",
            case["name"]
        );
    }
    // The add_blank interleave.
    let interleave = &traces["add_blank_case"];
    let phones: Vec<String> = interleave["input_phones"]
        .as_array()
        .expect("input phones")
        .iter()
        .map(|v| v.as_str().expect("phone").to_string())
        .collect();
    let tones = i32_vec(&interleave["input_tones"]);
    let (blank_phones, blank_tones) = add_blank_interleave(&phones, &tones);
    assert_eq!(
        blank_phones,
        interleave["phones"]
            .as_array()
            .expect("phones")
            .iter()
            .map(|v| v.as_str().expect("phone").to_string())
            .collect::<Vec<_>>()
    );
    let _ = blank_tones;
    let (ids, tone_ids, lang_ids) =
        cleaned_text_to_sequence(&blank_phones, &blank_tones, "EN", &symbols);
    assert_eq!(ids, i32_vec(&interleave["phone_ids"]));
    assert_eq!(tone_ids, i32_vec(&interleave["tone_ids"]));
    assert_eq!(lang_ids, i32_vec(&interleave["lang_ids"]));
}

#[test]
fn distribute_phone_fills_the_smallest_buckets() {
    // The reference greedy fill: every phone lands in the currently
    // smallest group.
    assert_eq!(super::distribute_phone(5, 2), vec![3, 2]);
    assert_eq!(super::distribute_phone(0, 3), vec![0, 0, 0]);
    assert_eq!(super::distribute_phone(4, 4), vec![1, 1, 1, 1]);
    assert_eq!(super::distribute_phone(6, 4), vec![2, 2, 1, 1]);
}

fn family_model() -> Model {
    Model::open(&testdata("stages")).expect("family model loads")
}

#[test]
fn bert_features_match_the_reference() {
    let traces = read_json(&testdata("bert/traces.json"));
    let dims = super::BertDims::from_json(Some(
        &serde_json::from_str::<Value>(
            &std::fs::read_to_string(testdata("bert/config.json")).expect("bert config"),
        )
        .expect("json"),
    ));
    let file = turbospark_model_io::safetensors::SafetensorsFile::open(&testdata(
        "bert/model.safetensors",
    ))
    .expect("bert weights");
    let bert = super::BertModel::load(&file, &dims).expect("bert loads");
    for case in traces["cases"].as_array().expect("cases") {
        let input_ids = i32_vec(&case["input_ids"]);
        let token_type_ids = vec![0i32; input_ids.len()];
        let mask = i32_vec(&case["attention_mask"]);
        let word2ph = case["word2ph"]
            .as_array()
            .expect("word2ph")
            .iter()
            .map(|v| v.as_u64().expect("count") as usize)
            .collect::<Vec<_>>();
        let ids_u32: Vec<u32> = input_ids.iter().map(|v| *v as u32).collect();
        let mask_u32: Vec<u32> = mask.iter().map(|v| *v as u32).collect();
        let types_u32: Vec<u32> = token_type_ids.iter().map(|v| *v as u32).collect();
        let name = case["name"].as_str().unwrap_or("?").to_string();
        let got = bert
            .phone_features(&ids_u32, &types_u32, Some(&mask_u32), &word2ph)
            .expect("features");
        assert_close(
            &got,
            &f32_vec(&case["features"]),
            FEATURE_TOLERANCE,
            &format!("bert features {name}"),
        );
        // The pooled CLS trace exercises the last hidden state.
        let pooled = bert
            .pooled(&ids_u32, &types_u32, Some(&mask_u32))
            .expect("pooled");
        assert!(
            pooled.iter().all(|v| v.is_finite()),
            "bert pooled {name}: non-finite output"
        );
        assert_close(
            &pooled,
            &f32_vec(&case["pooled"]),
            FEATURE_TOLERANCE,
            &format!("bert pooled {name}"),
        );
    }
}

#[test]
fn config_parses_fields_and_defaults() {
    let config: Value = serde_json::from_str(
        &std::fs::read_to_string(testdata("stages/config.json")).expect("config"),
    )
    .expect("json");
    let parsed = super::ModelConfig::from_json(&config).expect("parses");
    assert_eq!(parsed.sampling_rate, 44100);
    assert_eq!(parsed.filter_length, 64);
    assert_eq!(parsed.hop_length, 16);
    assert!(parsed.add_blank);
    assert_eq!(parsed.n_speakers, 4);
    assert_eq!(parsed.spk2id.get("EN-US"), Some(&1));
    assert_eq!(parsed.inter_channels, 32);
    assert_eq!(parsed.hidden_channels, 32);
    assert_eq!(parsed.filter_channels, 64);
    assert_eq!(parsed.n_layers, 2);
    assert_eq!(parsed.n_layers_trans_flow, 2);
    assert_eq!(parsed.gin_channels, 16);
    assert_eq!(parsed.num_tones, 16);
    assert_eq!(parsed.num_languages, 10);
    assert_eq!(parsed.bert_hidden_size, 1024);
    assert_eq!(parsed.bert.hidden_size, 16, "fixture bert dims override");
    assert_eq!(parsed.bert.num_hidden_layers, 2);
    // The reference defaults without overrides.
    let defaults = super::ModelConfig::from_json(&serde_json::json!({
        "sampling_rate": 44100,
        "symbols": ["_", "a"],
        "n_vocab": 2
    }))
    .expect("defaults");
    assert_eq!(defaults.filter_length, 2048);
    assert_eq!(defaults.hop_length, 512);
    assert_eq!(defaults.inter_channels, 192);
    assert_eq!(defaults.hidden_channels, 192);
    assert_eq!(defaults.filter_channels, 768);
    assert_eq!(defaults.n_heads, 2);
    assert_eq!(defaults.n_layers, 6);
    assert_eq!(defaults.n_layers_trans_flow, 3);
    assert_eq!(defaults.gin_channels, 256);
    assert_eq!(defaults.upsample_initial_channel, 512);
    assert_eq!(defaults.bert_hidden_size, 1024);
    assert_eq!(defaults.bert.hidden_size, 768);
    assert_eq!(defaults.bert.num_hidden_layers, 12);
    assert_eq!(defaults.sampling_rate, 44100);
}

#[test]
fn e2e_scenarios_match_the_reference() {
    let traces = read_json(&testdata("generate/traces.json"));
    let model = family_model();
    let symbols: Vec<String> = model.config().symbols.clone();
    for scenario in traces["scenarios"].as_array().expect("scenarios") {
        let name = scenario["name"].as_str().expect("name");
        // The text pipeline.
        assert_eq!(
            text_normalize(scenario["text"].as_str().expect("text")),
            scenario["norm_text"].as_str().expect("norm_text"),
            "{name} norm text"
        );
        // The pinned g2p stand-in through the Rust mapping.
        let mut phones = Vec::new();
        let mut tones = Vec::new();
        for word in scenario["word_phones"].as_array().expect("words") {
            for ph in word.as_array().expect("phones") {
                let (p, t) = refine_ph(ph.as_str().expect("phone"));
                phones.push(post_replace_ph(&p, &symbols, &super::text::PU_SYMBOLS));
                tones.push(t);
            }
        }
        phones.insert(0, "_".to_string());
        phones.push("_".to_string());
        tones.insert(0, 0);
        tones.push(0);
        assert_eq!(
            phones,
            scenario["phones"]
                .as_array()
                .expect("phones")
                .iter()
                .map(|v| v.as_str().expect("phone").to_string())
                .collect::<Vec<_>>(),
            "{name} phones"
        );
        let (blank_phones, blank_tones) = add_blank_interleave(&phones, &tones);
        let (phone_ids, tone_ids, lang_ids) =
            cleaned_text_to_sequence(&blank_phones, &blank_tones, "EN", &symbols);
        assert_eq!(phone_ids, i32_vec(&scenario["phone_ids"]), "{name} ids");
        assert_eq!(tone_ids, i32_vec(&scenario["tone_ids"]), "{name} tone ids");
        assert_eq!(lang_ids, i32_vec(&scenario["lang_ids"]), "{name} lang ids");
        let ja = f32_vec(&scenario["ja_bert"]);
        let audio = model
            .infer(
                &phone_ids.iter().map(|v| *v as u32).collect::<Vec<_>>(),
                &tone_ids.iter().map(|v| *v as u32).collect::<Vec<_>>(),
                &lang_ids.iter().map(|v| *v as u32).collect::<Vec<_>>(),
                scenario["sid"].as_i64().expect("sid") as i32,
                // The 1024-dim bert input stays zeros, exactly like the
                // shipped `_prepare_inputs` (`mx.zeros((1, 1024, n))`).
                &vec![0.0f32; model.config().bert_hidden_size * phone_ids.len()],
                &ja,
                0.1,
                1.0,
                4321,
                0.0,
            )
            .unwrap_or_else(|e| panic!("{name}: {e}"));
        let want = f32_vec(&scenario["audio"]);
        assert_eq!(audio.len(), want.len(), "{name} audio length");
        assert_close(&audio, &want, AUDIO_TOLERANCE, &format!("{name} audio"));
    }
}

#[test]
fn stage_pipeline_matches_the_reference() {
    let traces = read_json(&testdata("stages/traces.json"));
    let model = family_model();
    let case = &traces["cases"][0];
    let ids = i32_vec(&case["input_ids"]);
    let tone_ids = i32_vec(&case["tone_ids"]);
    let lang_ids = i32_vec(&case["lang_ids"]);
    let ja = f32_vec(&case["ja_bert"]);
    let t = ids.len();
    let _ja_dim = ja.len() / t;
    // Mirror the reference infer internals with private access.
    let gin = model.config().gin_channels;
    let sid = case["sid"].as_i64().expect("sid") as i32;
    let g = model.emb_g[sid as usize * gin..(sid as usize + 1) * gin].to_vec();
    assert_close(&g, &f32_vec(&case["g"]), FEATURE_TOLERANCE, "g");
    let (x, m_p, logs_p, _t) = model
        .enc_p
        .forward(
            &ids.iter().map(|v| *v as u32).collect::<Vec<_>>(),
            &tone_ids.iter().map(|v| *v as u32).collect::<Vec<_>>(),
            &lang_ids.iter().map(|v| *v as u32).collect::<Vec<_>>(),
            &vec![0.0f32; model.config().bert_hidden_size * t],
            &ja,
            t,
            Some(&g),
        )
        .expect("enc_p");
    assert_close(&x, &f32_vec(&case["x"]), FEATURE_TOLERANCE, "x");
    assert_close(&m_p, &f32_vec(&case["m_p"]), FEATURE_TOLERANCE, "m_p");
    assert_close(
        &logs_p,
        &f32_vec(&case["logs_p"]),
        FEATURE_TOLERANCE,
        "logs_p",
    );
    let logw = model.dp.forward(&x, t, Some(&g));
    assert_close(&logw, &f32_vec(&case["logw_dp"]), FEATURE_TOLERANCE, "logw");
    let _length_scale = 1.0f32;
    let mut w_ceil = vec![0.0f32; t];
    let mut y_frames = 0usize;
    for (i, v) in logw.iter().enumerate() {
        let ceil = v.exp().max(0.0).ceil();
        w_ceil[i] = ceil;
        y_frames += ceil as usize;
    }
    assert_close(
        &w_ceil,
        &f32_vec(&case["w_ceil"]),
        FEATURE_TOLERANCE,
        "w_ceil",
    );
    assert_eq!(
        y_frames,
        case["y_lengths"].as_array().expect("y")[0]
            .as_u64()
            .expect("y") as usize
    );
    // Alignment.
    let mut cum = vec![0.0f32; t];
    let mut running = 0.0f32;
    for (i, v) in w_ceil.iter().enumerate() {
        running += v;
        cum[i] = running;
    }
    let mut attn = vec![0.0f32; t * y_frames];
    for (i, window) in attn.chunks_mut(y_frames).enumerate() {
        let start = if i == 0 { 0.0 } else { cum[i - 1] };
        for (y, slot) in window.iter_mut().enumerate() {
            if (y as f32) >= start && (y as f32) < cum[i] {
                *slot = 1.0;
            }
        }
    }
    assert_close(&attn, &f32_vec(&case["attn"]), FEATURE_TOLERANCE, "attn");
    let align = |features: &[f32]| -> Vec<f32> {
        let channels = features.len() / t;
        let mut out = vec![0.0f32; channels * y_frames];
        for c in 0..channels {
            for (x_frame, window) in attn.chunks(y_frames).enumerate() {
                for (y_frame, w) in window.iter().enumerate() {
                    out[c * y_frames + y_frame] += features[c * t + x_frame] * w;
                }
            }
        }
        out
    };
    let m_aligned = align(&m_p);
    let logs_aligned = align(&logs_p);
    assert_close(
        &m_aligned,
        &f32_vec(&case["m_p_aligned"]),
        FEATURE_TOLERANCE,
        "m aligned",
    );
    assert_close(
        &logs_aligned,
        &f32_vec(&case["logs_p_aligned"]),
        FEATURE_TOLERANCE,
        "logs aligned",
    );
    // The latent draw.
    let mut rng = super::Rng::new(4321);
    let noise = rng.normal(m_aligned.len());
    let mut z_p = vec![0.0f32; m_aligned.len()];
    for ((z, m), (n, l)) in z_p
        .iter_mut()
        .zip(&m_aligned)
        .zip(noise.iter().zip(&logs_aligned))
    {
        *z = m + n * l.exp() * 0.1;
    }
    assert_close(&z_p, &f32_vec(&case["z_p"]), FEATURE_TOLERANCE, "z_p");
    // The reverse flow: a channel flip before every coupling layer.
    let flow_steps = case["flow_z"].as_array().expect("flow steps");
    let channels = model.config().inter_channels;
    let mut latent = z_p.clone();
    for (i, layer) in model.flow_layers.iter().rev().enumerate() {
        latent = super::flip_channels(&latent, y_frames, channels);
        latent = layer.reverse(&latent, y_frames, Some(&g));
        assert_close(
            &latent,
            &f32_vec(&flow_steps[i]),
            FEATURE_TOLERANCE,
            &format!("flow step {i}"),
        );
    }
    assert_close(&latent, &f32_vec(&case["z"]), FEATURE_TOLERANCE, "z");
    // The same path through the model entry point.
    let via_model = model.flow_reverse(&z_p, y_frames, Some(&g));
    assert_close(
        &via_model,
        &f32_vec(&case["z"]),
        FEATURE_TOLERANCE,
        "z via model",
    );
    let audio = model.dec.forward(&latent, Some(&g));
    assert_close(&audio, &f32_vec(&case["audio"]), AUDIO_TOLERANCE, "audio");
}

/// The bert and ja_bert slices must match `in_ch x tokens` exactly. The
/// old `zip` accepted short or long slices and silently dropped data.
#[test]
fn enc_p_rejects_mismatched_bert_lengths() {
    let model = family_model();
    let ids = [0u32, 1, 2];
    let tones = [7u32; 3];
    let langs = [2u32; 3];
    let bert_ch = model.enc_p.bert_proj.in_ch;
    let ja_ch = model.enc_p.ja_bert_proj.in_ch;
    let bert = vec![0.0f32; bert_ch * 3];
    let ja = vec![0.0f32; ja_ch * 3];
    model
        .enc_p
        .forward(&ids, &tones, &langs, &bert, &ja, 3, None)
        .expect("exact lengths are accepted");
    let short_bert = &bert[..bert.len() - 1];
    assert!(model
        .enc_p
        .forward(&ids, &tones, &langs, short_bert, &ja, 3, None)
        .is_err());
    let long_ja = vec![0.0f32; ja_ch * 3 + 1];
    assert!(model
        .enc_p
        .forward(&ids, &tones, &langs, &bert, &long_ja, 3, None)
        .is_err());
}

/// Malformed HiFi-GAN lists are rejected at load instead of panicking or
/// underflowing (`k - u`) or dividing by zero resblock kernels.
#[test]
fn hifigan_rejects_malformed_list_lengths() {
    let config = |kernels: &str, rates: &str, upk: &str, dil: &str| {
        super::ModelConfig::from_json(
            &serde_json::from_str(&format!(
                r#"{{"symbols": [], "resblock_kernel_sizes": {kernels},
                    "resblock_dilation_sizes": {dil}, "upsample_rates": {rates},
                    "upsample_kernel_sizes": {upk}}}"#
            ))
            .unwrap(),
        )
        .unwrap()
    };
    let ok_dil = "[[1,3,5],[1,3,5],[1,3,5]]";
    super::check_hifigan_lists(&config("[3,7,11]", "[8,8]", "[16,16]", ok_dil))
        .expect("well-formed lists are accepted");
    // Fewer upsample kernels than rates.
    assert!(super::check_hifigan_lists(&config("[3,7,11]", "[8,8]", "[16]", ok_dil)).is_err());
    // Kernel smaller than its stride would underflow `k - u`.
    assert!(super::check_hifigan_lists(&config("[3,7,11]", "[8,8]", "[4,16]", ok_dil)).is_err());
    // Fewer dilation lists than resblock kernels.
    assert!(
        super::check_hifigan_lists(&config("[3,7,11]", "[8,8]", "[16,16]", "[[1,3,5]]")).is_err()
    );
    // No resblock kernels would divide by zero in the average.
    assert!(super::check_hifigan_lists(&config("[]", "[8,8]", "[16,16]", "[]")).is_err());
}

#[test]
fn infer_refuses_bad_inputs() {
    let model = family_model();
    let ids = vec![0u32, 1, 2];
    let tones = vec![7u32; 3];
    let langs = vec![2u32; 3];
    let ja = vec![0.0f32; 16 * 3];
    let bert = vec![0.0f32; model.config().bert_hidden_size * 3];
    let error = model
        .infer(&ids, &tones, &langs, 999, &bert, &ja, 0.1, 1.0, 1, 0.0)
        .unwrap_err();
    assert!(error.to_string().contains("speaker id"), "{error}");
    let error = model
        .infer(&ids, &tones[..2], &langs, 0, &bert, &ja, 0.1, 1.0, 1, 0.0)
        .unwrap_err();
    assert!(
        error.to_string().contains("match the phone count"),
        "{error}"
    );
    let error = model
        .infer(&ids, &tones, &langs, 0, &bert, &ja, 0.1, 1.0, 1, 0.5)
        .unwrap_err();
    assert!(error.to_string().contains("sdp_ratio"), "{error}");
    let error = model
        .infer(
            &[0, 9999, 0],
            &tones,
            &langs,
            0,
            &bert,
            &ja,
            0.1,
            1.0,
            1,
            0.0,
        )
        .unwrap_err();
    assert!(error.to_string().contains("phone ids"), "{error}");
}

#[test]
fn resolve_speaker_falls_through_the_reference_chain() {
    let model = family_model();
    // spk2id: EN-Default -> 0, EN-US -> 1.
    assert_eq!(model.resolve_speaker(Some("EN-US"), "EN-US"), 1);
    assert_eq!(model.resolve_speaker(Some("missing"), "EN-US"), 1);
    assert_eq!(model.resolve_speaker(Some("missing"), "EN"), 0);
    assert_eq!(model.resolve_speaker(None, "ZH"), 0);
}
